-- Adds institution-managed portal hostnames with DNS TXT ownership verification.
-- This script defines API permission mappings only; it does not grant any role.

BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."InstitutionPortalDomainMaster" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "DomainName" varchar(253) NOT NULL,
    "ChallengeValueHash" varchar(64) NOT NULL,
    "ChallengeExpiresAt" timestamp with time zone NOT NULL,
    "VerificationStatus" smallint NOT NULL DEFAULT 1,
    "VerifiedAt" timestamp with time zone,
    "IsActive" boolean NOT NULL DEFAULT false,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp with time zone,
    "SoftDeletedById" bigint,
    "DeletedDateTime" timestamp with time zone,
    CONSTRAINT "FK_InstitutionPortalDomainMaster_Institution"
        FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_InstitutionPortalDomainMaster_VerificationStatus"
        CHECK ("VerificationStatus" IN (1, 2)),
    CONSTRAINT "CK_InstitutionPortalDomainMaster_VerifiedActive"
        CHECK (NOT "IsActive" OR ("VerificationStatus" = 2 AND "VerifiedAt" IS NOT NULL))
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_InstitutionPortalDomainMaster_Institution"
    ON skolenza."InstitutionPortalDomainMaster" ("InstitutionId")
    WHERE NOT "IsSoftDeleted";

CREATE UNIQUE INDEX IF NOT EXISTS "UX_InstitutionPortalDomainMaster_Domain"
    ON skolenza."InstitutionPortalDomainMaster" (lower("DomainName"))
    WHERE NOT "IsSoftDeleted";

CREATE INDEX IF NOT EXISTS "IX_InstitutionPortalDomainMaster_VerifiedActive"
    ON skolenza."InstitutionPortalDomainMaster" ("DomainName", "InstitutionId")
    WHERE "IsActive" AND "VerificationStatus" = 2 AND NOT "IsSoftDeleted";

INSERT INTO skolenza."Module"
    ("InstitutionId", "ModuleCode", "ModuleName", "DisplayName", "URLPath", "ParentModuleId", "IsLeafNode",
     "IsModuleDisplayInUI", "IsCommonMenu", "IsActive", "ImageIconWeb", "ImageIconMobile", "ItemPriority",
     "Remark", "AddedById", "AddedDateTime", "ModuleScope")
SELECT NULL, 'STUDENT_PORTAL_DOMAINS', 'Student-Portal-Domains', 'Student Portal Domains',
       '/app/student-portal-domains', NULL, TRUE, TRUE, FALSE, TRUE,
       'bi bi-globe2', 'globe', 580,
       'Institution portal domain ownership and DNS verification API permission.',
       1, CURRENT_TIMESTAMP, 1
WHERE NOT EXISTS (
    SELECT 1 FROM skolenza."Module" WHERE "ModuleCode" = 'STUDENT_PORTAL_DOMAINS'
);

INSERT INTO skolenza."ModuleOperationMapping"
    ("ModuleId", "OperationId", "PageURL", "IconURL", "IsCommonItem", "IsOperational", "Priority", "Remark",
     "IsActive", "AddedById", "AddedDateTime")
SELECT module."Id", operation."Id", module."URLPath", module."ImageIconWeb", FALSE, TRUE,
       CASE lower(btrim(operation."OperationName"))
           WHEN 'view' THEN 10 WHEN 'add' THEN 20 WHEN 'update' THEN 30 WHEN 'delete' THEN 40 ELSE 99 END,
       'Institution portal domain ownership API permission.', TRUE, 1, CURRENT_TIMESTAMP
FROM skolenza."Module" module
CROSS JOIN skolenza."Operation" operation
WHERE module."ModuleCode" = 'STUDENT_PORTAL_DOMAINS'
  AND lower(btrim(operation."OperationName")) IN ('view', 'add', 'update', 'delete')
  AND operation."IsActive"
  AND NOT EXISTS (
      SELECT 1 FROM skolenza."ModuleOperationMapping" existing
      WHERE existing."ModuleId" = module."Id" AND existing."OperationId" = operation."Id"
  );

COMMIT;
